// Memory router: minimal contracts for the five stores.
export interface MemoryStore {
  kind: 'scratchpad' | 'working' | 'episodic' | 'semantic' | 'procedural';
  read(query: { taskId: string; userId?: string; k?: number }): Promise<string[]>;
  write(item: { content: string; tags?: string[]; evidence?: number }): Promise<void>;
  compact(budgetTokens: number): Promise<void>;
}

// Policy: when to write to which store.
export function classifyForMemory(text: string): MemoryStore['kind'] | null {
  if (/^I (always|prefer|usually)/i.test(text)) return 'semantic';
  if (/^step \d+:/i.test(text)) return 'procedural';
  if (text.length > 600) return 'episodic';
  return 'working';
}

// Compose a turn's context budget across stores.
export async function packContext(stores: Record<MemoryStore['kind'], MemoryStore>, taskId: string, userId: string) {
  const [semantic, procedural, episodic] = await Promise.all([
    stores.semantic.read({ taskId, userId, k: 5 }),
    stores.procedural.read({ taskId, k: 1 }),
    stores.episodic.read({ taskId, userId, k: 3 }),
  ]);
  return [
    semantic.length ? `<facts>\n${semantic.join('\n')}\n</facts>` : '',
    procedural.length ? `<playbook>\n${procedural[0]}\n</playbook>` : '',
    episodic.length ? `<past-episodes>\n${episodic.join('\n---\n')}\n</past-episodes>` : '',
  ].filter(Boolean).join('\n\n');
}
